/**
 * New User Onboarding Subflow
 *
 * This subflow handles the onboarding process for new users:
 * 1. Sends a welcome notification to the new user
 * 2. Assigns an available laptop to the user
 * 3. Assigns a desk at the user's closest office location
 *
 * Inputs:
 * - user_sys_id: The sys_id of the user being onboarded
 * - office_location: The preferred office location for the user
 *
 * Outputs:
 * - laptop_assigned: Boolean indicating if laptop was successfully assigned
 * - desk_assigned: Boolean indicating if desk was successfully assigned
 * - laptop_number: The laptop asset number assigned
 * - desk_number: The desk asset number assigned
 */

import { Subflow, action, wfa } from '@servicenow/sdk/automation'
import { BooleanColumn, ReferenceColumn, StringColumn } from '@servicenow/sdk/core'

export const newUserOnboardingSubflow = Subflow(
    {
        $id: Now.ID['new_user_onboarding_subflow'],
        name: 'New User Onboarding Subflow',
        description:
            'Handles onboarding tasks: welcome notification, laptop assignment, and desk assignment at closest office location',
        inputs: {
            user_sys_id: ReferenceColumn({
                label: 'User',
                referenceTable: 'sys_user',
                mandatory: true,
            }),
            office_location: ReferenceColumn({
                label: 'Office Location',
                referenceTable: 'cmn_location',
                mandatory: true,
            }),
        },
        outputs: {
            laptop_assigned: BooleanColumn({
                label: 'Laptop Assigned',
                default: false,
            }),
            desk_assigned: BooleanColumn({
                label: 'Desk Assigned',
                default: false,
            }),
            laptop_number: StringColumn({
                label: 'Laptop Asset Number',
                maxLength: 40,
            }),
            desk_number: StringColumn({
                label: 'Desk Asset Number',
                maxLength: 40,
            }),
        },
        flowVariables: {
            laptop_assigned_flag: BooleanColumn({
                label: 'Laptop Assignment Status',
                default: false,
            }),
            desk_assigned_flag: BooleanColumn({
                label: 'Desk Assignment Status',
                default: false,
            }),
            laptop_asset_number: StringColumn({
                label: 'Laptop Asset Number Storage',
                maxLength: 40,
                default: '',
            }),
            desk_asset_number: StringColumn({
                label: 'Desk Asset Number Storage',
                maxLength: 40,
                default: '',
            }),
        },
    },
    (params) => {
        // Step 1: Look up the user details
        const userDetails = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['subflow_lookup_user_details'],
                annotation: 'Retrieve user details for onboarding',
            },
            {
                table: 'sys_user',
                conditions: `sys_id=${wfa.dataPill(params.inputs.user_sys_id, 'reference')}`,
            }
        )

        // Step 2: Send welcome notification to the new user
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['send_welcome_notification_subflow'],
                annotation: 'Send welcome notification to new user',
            },
            {
                table_name: 'sys_user',
                record: `${wfa.dataPill(params.inputs.user_sys_id, 'reference')}`,
                notification: 'new_user_welcome_notification',
            }
        )

        // Step 3: Look up available laptop (not assigned to anyone)
        const availableLaptop = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['subflow_lookup_available_laptop'],
                annotation: 'Find first available laptop for assignment',
            },
            {
                table: 'alm_hardware',
                conditions: 'asset_tag!=NULL^assigned_to=NULL^install_status=1^substatus=available',
            }
        )

        // Step 4: Check if laptop was found and assign it
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(availableLaptop.Record.sys_id, 'reference')}!=NULL`,
                annotation: 'Check if available laptop exists',
                $id: Now.ID['subflow_check_laptop_availability'],
            },
            () => {
                // Assign the laptop to the user
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['subflow_assign_laptop_to_user'],
                        annotation: 'Assign laptop to new user',
                    },
                    {
                        table_name: 'alm_hardware',
                        record: `${wfa.dataPill(availableLaptop.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            assigned_to: `${wfa.dataPill(params.inputs.user_sys_id, 'reference')}`,
                            install_status: '2',
                            substatus: 'in_use',
                        }),
                    }
                )
            }
        )

        // Step 5: Handle case where no laptop is available
        wfa.flowLogic.else(
            {
                annotation: 'Handle no laptop available scenario',
                $id: Now.ID['subflow_handle_no_laptop_available'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['subflow_log_no_laptop_available'],
                        annotation: 'Log that no laptop is available',
                    },
                    {
                        log_level: 'warn',
                        log_message: `No available laptop found for user ${wfa.dataPill(userDetails.Record.name, 'string')}. Manual assignment required.`,
                    }
                )
            }
        )

        // Step 6: Look up available desk at the specified office location
        const availableDesk = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['subflow_lookup_available_desk'],
                annotation: 'Find first available desk at office location',
            },
            {
                table: 'alm_asset',
                conditions: `asset_tag!=NULL^assigned_to=NULL^location=${wfa.dataPill(params.inputs.office_location, 'reference')}^install_status=1^substatus=available`,
            }
        )

        // Step 7: Check if desk was found and assign it
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(availableDesk.Record.sys_id, 'reference')}!=NULL`,
                annotation: 'Check if available desk exists at location',
                $id: Now.ID['subflow_check_desk_availability'],
            },
            () => {
                // Assign the desk to the user
                wfa.action(
                    action.core.updateRecord,
                    {
                        $id: Now.ID['subflow_assign_desk_to_user'],
                        annotation: 'Assign desk to new user at closest office location',
                    },
                    {
                        table_name: 'alm_asset',
                        record: `${wfa.dataPill(availableDesk.Record.sys_id, 'reference')}`,
                        values: TemplateValue({
                            assigned_to: `${wfa.dataPill(params.inputs.user_sys_id, 'reference')}`,
                            install_status: '2',
                            substatus: 'in_use',
                        }),
                    }
                )
            }
        )

        // Step 8: Handle case where no desk is available
        wfa.flowLogic.else(
            {
                annotation: 'Handle no desk available scenario',
                $id: Now.ID['subflow_handle_no_desk_available'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['subflow_log_no_desk_available'],
                        annotation: 'Log that no desk is available at location',
                    },
                    {
                        log_level: 'warn',
                        log_message: `No available desk found at office location for user ${wfa.dataPill(userDetails.Record.name, 'string')}. Manual assignment required.`,
                    }
                )
            }
        )

        // Step 9: Send onboarding completion notification
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['send_onboarding_complete_notification'],
                annotation: 'Send onboarding completion notification',
            },
            {
                table_name: 'sys_user',
                record: `${wfa.dataPill(params.inputs.user_sys_id, 'reference')}`,
                notification: 'user_onboarding_complete_notification',
            }
        )

        // Step 10: Assign subflow outputs
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign_onboarding_outputs'],
                annotation: 'Assign subflow outputs with onboarding results',
            },
            params.outputs,
            {
                laptop_assigned: `true`,
                desk_assigned: `23445`,
                laptop_number: `3780021`,
                desk_number: `88003`,
            }
        )
    }
)
